import { describe, it } from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { spawnSync } from "node:child_process";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");

describe("content bundle", () => {
  it("builds a classic script without import or export", () => {
    const result = spawnSync(process.execPath, [join(root, "scripts/bundle-content.mjs")], {
      encoding: "utf8",
    });
    assert.equal(result.status, 0, result.stderr);
    const bundle = readFileSync(join(root, "content/injected.js"), "utf8");
    assert.match(bundle, /Generated by scripts\/bundle-content\.mjs/);
    assert.equal(bundle.includes("import "), false);
    assert.equal(/\bexport\s/.test(bundle), false);
    assert.match(bundle, /PipAddonContent/);
    assert.match(bundle, /class PipPlayer/);
  });
});
